"""Persistent shared JSON cache for public demonstration profiles."""
import json
import os
import time
import fcntl
from app.config import CACHE_PATH, CACHE_TTL


def get_or_load(key, loader, now=None):
    if now is None:
        now = time.time()
    cache = _read_cache()
    entry = cache.get(key)
    if entry is not None and (now - entry["stored_at"]) < CACHE_TTL:
        return entry["value"]
    value = loader()
    cache[key] = {"stored_at": now, "value": value}
    _write_cache(cache)
    return value


def _read_cache():
    if not os.path.exists(CACHE_PATH):
        return {}
    try:
        with open(CACHE_PATH, "r") as f:
            fcntl.flock(f, fcntl.LOCK_SH)
            data = json.load(f)
            fcntl.flock(f, fcntl.LOCK_UN)
            return data
    except (json.JSONDecodeError, OSError):
        return {}


def _write_cache(cache):
    os.makedirs(os.path.dirname(CACHE_PATH), exist_ok=True)
    with open(CACHE_PATH, "w") as f:
        fcntl.flock(f, fcntl.LOCK_EX)
        json.dump(cache, f)
        f.flush()
        os.fsync(f.fileno())
        fcntl.flock(f, fcntl.LOCK_UN)
EOF"}

